tools.example:
foreach s [get_bd_addr_segs -addressing -of_objects [get_bd_addr_spaces processing_system7_0/Data]] {
  puts [format "%-40s 0x%08X %s" $s [get_property OFFSET $s] [get_property RANGE $s]]
}

# unconnected clock pins in the whole design
foreach p [get_bd_pins -hierarchical -filter {TYPE == clk && DIR == I}] {
  if {[get_bd_nets -of_objects $p -quiet] eq ""} { puts "undriven clock: $p" }
}
get_bd_intf_nets -of_objects [get_bd_intf_pins axi_dma_0/M_AXI_S2MM]
set_property CONFIG.FREQ_HZ 200000000 [get_bd_ports clk_200]

get_board_parts -latest_file_version -filter {VENDOR_NAME == digilentinc.com}
get_board_part_interfaces -of_objects [get_board_parts xilinx.com:kcu105:part0:1.7]
get_board_part_pins -of_objects [get_board_part_interfaces led_8bits]
